package dev.eugheist.ttmodern;
final class LocomotiveMovableAudit {
 static void run(net.minecraft.server.level.ServerLevel world,net.minecraft.core.BlockPos start,net.minecraft.core.BlockPos left,net.minecraft.core.BlockPos right){
  var blocks=new java.util.ArrayList<net.minecraft.world.level.block.Block>();blocks.addAll(java.util.List.of(ThaumicTinkererModern.MAGNET.get(),ThaumicTinkererModern.MOB_MAGNET.get(),ThaumicTinkererModern.INTERFACE.get(),ThaumicTinkererModern.DISLOCATOR.get(),ThaumicTinkererModern.PLATFORM.get(),ThaumicTinkererModern.ANIMATION_TABLET.get(),ThaumicTinkererModern.LOCOMOTIVE_RELAY.get(),ThaumicTinkererModern.REPAIRER.get(),ThaumicTinkererModern.ENCHANTER.get()));if(net.neoforged.fml.ModList.get().isLoaded("computercraft")){blocks.add(GolemConnector.BLOCK.get());blocks.add(AspectAnalyzer.BLOCK.get());}int i=0;
  for(var block:blocks){
   for(var pos:java.util.List.of(start,start.above(),start.east(),start.east().above())){world.removeBlockEntity(pos);world.setBlock(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);}
   world.setBlock(start,ThaumicTinkererModern.LOCOMOTIVE.get().defaultBlockState(),3);var train=(LocomotiveEntity)world.getBlockEntity(start);train.first=left;train.second=right;train.linked=true;train.direction=net.minecraft.core.Direction.EAST;
   world.setBlock(start.above(),block.defaultBlockState(),3);var passenger=world.getBlockEntity(start.above());LocomotiveAudit.check(passenger instanceof MovableTile,"original movable passenger "+block);
   if(passenger instanceof TransvectorEntity device){device.camouflage(net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());LocomotiveAudit.check(device.link(start),"moving interface retains absolute locomotive link");}
   if(passenger instanceof DislocatorEntity device){device.camouflage(net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());LocomotiveAudit.check(device.link(start.north()),"moving dislocator retains absolute link");}
   if(passenger instanceof PlatformEntity platform)platform.camouflage(net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());
   if(passenger instanceof LocomotiveRelayEntity relay)relay.partner=right;
   if(net.neoforged.fml.ModList.get().isLoaded("computercraft")&&passenger instanceof GolemConnector.Entity connector){connector.camouflage(net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());connector.connect(java.util.UUID.fromString("ff1d00c9-1fd9-462a-bdab-a6ab516f6c73"));}
   if(passenger instanceof MagnetEntity magnet){magnet.adult=false;var mould=new net.minecraft.world.item.ItemStack(ThaumicTinkererModern.SOUL_MOULD.get());mould.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Movable filter conservation"));magnet.inventory.setStackInSlot(0,mould);}
   if(passenger instanceof AnimationTabletEntity tablet){tablet.inventory.setStackInSlot(0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_PICKAXE));tablet.breaking=true;tablet.damage=.5f;}
   if(passenger instanceof RepairerEntity repairer){var tool=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_PICKAXE);tool.setDamageValue(53);repairer.inventory.setStackInSlot(0,tool);repairer.repairing=true;}
   if(passenger instanceof EnchanterEntity enchanter){var tool=new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND_SWORD);tool.setDamageValue(27);enchanter.inventory.setStackInSlot(0,tool);enchanter.inventory.setStackInSlot(1,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.BOOK,7));}
   if(net.neoforged.fml.ModList.get().isLoaded("computercraft")&&passenger instanceof AspectAnalyzer.Entity analyzer)analyzer.inventory.setStackInSlot(0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIRT,37));
   var expected=passenger.saveWithoutMetadata(world.registryAccess());LocomotiveAudit.tick(world,start,601+100L*i++);var moved=world.getBlockEntity(start.east().above());LocomotiveAudit.check(world.isEmptyBlock(start.above())&&moved!=null&&moved.getType()==passenger.getType(),"movable passenger moved "+block);LocomotiveAudit.check(moved.saveWithoutMetadata(world.registryAccess()).equals(expected),"movable passenger NBT preserved "+block);
   if(passenger instanceof AnimationTabletEntity tablet)LocomotiveAudit.check(!tablet.breaking&&tablet.damage==0,"moving tablet cancels old breaking progress");
   if(moved instanceof MagnetEntity magnet)magnet.inventory.setStackInSlot(0,net.minecraft.world.item.ItemStack.EMPTY);if(moved instanceof AnimationTabletEntity tablet)tablet.inventory.setStackInSlot(0,net.minecraft.world.item.ItemStack.EMPTY);
  }
  // Funnel's movable contract is also used by spatial movement; locomotive support is unsuitable.
  for(var pos:java.util.List.of(start,start.above(),start.east(),start.east().above())){world.removeBlockEntity(pos);world.setBlock(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);}
  world.setBlock(start,ThaumicTinkererModern.LOCOMOTIVE.get().defaultBlockState(),3);var train=(LocomotiveEntity)world.getBlockEntity(start);train.first=left;train.second=right;train.linked=true;train.direction=net.minecraft.core.Direction.EAST;
  world.setBlock(start.above(),ThaumicTinkererModern.FUNNEL.get().defaultBlockState(),net.minecraft.world.level.block.Block.UPDATE_CLIENTS|net.minecraft.world.level.block.Block.UPDATE_KNOWN_SHAPE);var funnel=(FunnelEntity)world.getBlockEntity(start.above());LocomotiveAudit.check(funnel instanceof MovableTile&&funnel.prepareToMove(),"original funnel movable contract");funnel.inventory.setStackInSlot(0,new net.minecraft.world.item.ItemStack(dev.eugheist.tc4modern.EssentiaDevices.JAR.get()));var funnelData=funnel.saveWithoutMetadata(world.registryAccess());LocomotiveAudit.tick(world,start,2001);LocomotiveAudit.check(world.getBlockEntity(start.above())==funnel&&funnel.saveWithoutMetadata(world.registryAccess()).equals(funnelData),"unsupported funnel left intact with stored jar");funnel.inventory.setStackInSlot(0,net.minecraft.world.item.ItemStack.EMPTY);
  LocomotiveAudit.check(world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(start).inflate(6)).isEmpty(),"movable passengers create no item drops");
  System.out.println("TT LOCOMOTIVE MOVABLE AUDIT: ALL PASS ("+blocks.size()+" original addon passenger variants,native movement,NBT/filter/tool conservation,tablet breaking cancellation,no drops)");
 }
}
